import hashlib
from pathlib import Path
from langchain_core.tools import tool
_EXTS = {'.jpg', '.jpeg', '.png', '.heic', '.mp4', '.mov'}

def _sha1(path):
    h = hashlib.sha1()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(1 << 20), b''):
            h.update(chunk)
    return h.hexdigest()

@tool
def find_duplicate_photos(library_path: str, min_size_kb: int=0) -> dict:
    root = Path(library_path)
    if not root.exists():
        return {'error': f'path not found: {library_path}'}
    if not root.is_dir():
        return {'error': 'library_path must be a directory'}
    if min_size_kb < 0:
        return {'error': 'min_size_kb must be >= 0'}
    # Clean up leftover temp files from interrupted imports before scanning
    for tmp in root.rglob('*.tmp'):
        if tmp.is_file():
            try:
                tmp.unlink()
            except OSError:
                pass
    seen = {}
    for p in root.rglob('*'):
        if not p.is_file() or p.suffix.lower() not in _EXTS:
            continue
        if p.stat().st_size < min_size_kb * 1024:
            continue
        seen.setdefault(_sha1(p), []).append(str(p))
    groups = [v for v in seen.values() if len(v) > 1]
    return {'group_count': len(groups), 'groups': groups}
